INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66099782', 66099782, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Pemeliharaan Portal Knowledge Hub  Program Kerja Sama Pemerintah RI-UNFPA Kegiatan Program Kerja Sama Pemerintah RI-UNFPA Siklus 11 (2026-2030) TA 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 65000000, 'February 2026', 'Lainnya', 1, 1, '1 Paket', 'Ruang lingkup pekerjaan Jasa Konsultan Pemeliharaan Portal Knowledge Hub Program Kerja Sama Pemerintah RI-UNFPA meliputi: 1. Melakukan pemeliharaan Portal Knowledge Hub secara rutin melalui pemeriksaan secara berkala, pembaruan sistem, memastikan keamanan serta performa, sehingga dapat berfungsi dengan optimal; 2. Mengidentifikasi, menganalisis, dan memperbaiki berbagai bug/eror baik pada front end maupun back end Portal Knowledge Hub, termasuk potensi kendala dalam integrasi dengan Microservice pengetahuan Pusdatinrenbang Kementerian PPN/Bappenas; 3. Menambahkan dan menyempurnakan fitur Portal Knowledge Hub sesuai dengan perkembangan kebutuhan, termasuk meningkatkan user experience (UX), antarmuka pengguna (UI), serta melakukan pemutakhiran panduan penggunaan teknisnya; 4. Memfasilitasi dukungan teknis terhadap kendala yang dihadapi oleh Mitra Pelaksana/Mitra Strategis dalam pengelolaan produk pengetahuan dalam Portal Knowledge Hub dengan memberikan panduan penggunaan, dokumentasi, dan troubleshooting; 5. Melakukan pengujian fungsionalitas, integrasi (API), kompatibilitas, keamanan, dan performa untuk memastikan kelancaran penggunaan portal sebelum dan sesudah menambahkan atau menyempurnakan fitur; 6. Menyusun dokumentasi pengembangan, pemeliharaan, catatan perubahan, serta laporan triwulanan mengenai aktivitas pemeliharaan dan rekomendasi peningkatan sistem ke depan; 7. Melakukan koordinasi aktif dengan Pusdatinrenbang Kementerian PPN/Bappenas dalam pengelolaan, pemeliharaan, dan optimalisasi server Portal Knowledge Hub; dan 8. Melakukan transfer of knowledge (Alih Pengetahuan) atas hasil pekerjaan kepada pemilik pekerjaan untuk memastikan keberlanjutan hasil pekerjaan dan membangun kemandirian internal.', 'Persyaratan penyedia Jasa Konsultan Pemeliharaan Portal Knowledge Hub Program Kerja Sama Pemerintah RI-UNFPA adalah sebagai berikut: 1. Minimum Sarjana Strata Satu (S1) dari Perguruan Tinggi Negeri (PTN) atau Perguruan Tinggi Swasta (PTS) bidang Teknik Informatika, Ilmu Komputer, Sistem Informasi, Teknik Elektronika atau Geodesy and Geomatics, GIS; 2. Berpengalaman minimal 3 (tiga) tahun di bidang software/web development dengan dashboards atau web-based input programs yang berhubungan, dibuktikan dengan kontrak atau referensi kerja sebelumnya; 3. Mampu menggunakan software seperti: PHP, MySQL, HTML, CSS, dan Javascript, serta familiar dengan UI/UX dibuktikan dengan portofolio pekerjaan sejenis; 4. Menguasai dan memahami: Software Documentation, System Design, Problem-solving, pengembangan dan integrasi Rest API, serta pemahaman terhadap DevOps Sistem (versioning, deployment, dan monitoring) dibuktikan dengan portofolio pekerjaan sejenis; dan 5. Bukan PNS atau anggota TNI/Polri.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 601477);
