INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62494427', 62494427, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN AGAMA CIANJUR 01', 'JASA OUTSOURCING - CLEANING SERVICE', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Barat, Cianjur (Kab.)', 196404000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 0, 1, '4 ORG @ 13 BULAN', 'Menjaga kebersihan lantai dengan menyapu dan mengepel setiap hari. Membersihkan debu pada permukaan, furnitur, dan area transparan seperti kaca. Menjaga kebersihan toilet dan area cuci tangan. Mengelola dan membuang sampah secara teratur. Menjaga kebersihan area umum seperti lobi, ruang tunggu, dan ruang makan/pantry. Merawat peralatan dan perlengkapan kebersihan yang digunakan', 'Kegiatan Persiapan Pelaksanaan Kontrak: 1) Rapat Persiapan Rencana Kerja 2) Penyampaian SOP Cleaning Service 3) Mapping area kantor Pengadilan Agama Cianjur Berdasarkan Jumlah Tenaga Outsourcing 4) Mobilisasi Tenaga Kemanan di sertai alat dan bahan yang mendukung kinerjanya. 5) Rencana Jadwal briefing dan pelatihan softskill/hardskill Tenaga Outsourcing Pekerjaan Tenaga Cleaning Service: 1) Mengikuti SOP Cleaning Service Perusahaan Penyedia 2) Mengikuti hasil monitoring dan evaluasi Pekerjaan Penyedia bila ada hal yang masih belum di atur atau masih ada kekurangan. Personil Tenaga Cleaning Service: - Umur 18-59 Tahun - Minimal Lulusan SMA - Sehat Jasmani dan Rohani Penyedia: 1. Melengkapi dokumen informasi penyedia berupa: a. Profil Perusahaan b. Akta Pendirian Perusahaan dan/atau perubahannya (akta perubahan bisa berlaku seluruhnya); c. NPWP Perusahaan; d. Rekning Perusahaan; e. Struktur Organisasi Perusahaan; f. Nomor Izin Berusaha; g. SPT Tahunan 2. Mengirimkan Tenaga Kerja dan Perlengakapan Pendukung Sesuai Surat Perintah Melaksanakan Kerja (SPMK) 3. Melaksanakan Monitoring dan Evaluasi 4. Membuat Laporan Bulanan terdiri dari: a. Surat Penyampaian Laporan dan permohonan pembayaran b. Bukti pembayaran BPJS Kesehatan dan Tenaga Kerja c. Invoice dan Faktur Pajak d. Daftar Hadir e. Dokumentasi pekerjaan f. Evaluasi Bulanan Penyedia terhadap Tenaga Kerja g. Barang-barang yang dikirimkan dan digunakan disertai bukti persetujuan dengan PPK', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 604748);
