INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66007912', 66007912, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'KANTOR PUSAT BADAN PERTANAHAN NASIONAL REPUBLIK INDONESIA', 'Konsultan Perorangan Bidang Kajian dan Pengembangan Kebijakan Pertanahan dan Tata Ruang', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 100000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Melakukan kajian terhadap peraturan, kebijakan, dan regulasi pertanahan dan tata ruang yang berlaku, baik di tingkat nasional maupun daerah. 2. Menyusun analisis kebijakan yang mencakup identifikasi isu strategis, tantangan, peluang, dan tren pengembangan pertanahan dan tata ruang. 3. Memberikan rekomendasi pengembangan kebijakan pertanahan dan tata ruang yang berbasis data, praktik terbaik, dan kebutuhan pembangunan nasional. 4. Melakukan telaahan terhadap rancangan kebijakan, keputusan, atau regulasi baru terkait pertanahan dan tata ruang agar selaras dengan peraturan perundang-undangan yang berlaku. 5. Menyusun kajian strategis yang mendukung perumusan kebijakan yang efektif, aplikatif, dan implementatif di lingkungan Kementerian ATR/BPN. 6. Memberikan masukan dan saran dalam rapat teknis atau konsultasi kebijakan yang diselenggarakan oleh Kementerian ATR/BPN.', '1. Melakukan kajian terhadap peraturan, kebijakan, dan regulasi pertanahan dan tata ruang yang berlaku, baik di tingkat nasional maupun daerah. 2. Menyusun analisis kebijakan yang mencakup identifikasi isu strategis, tantangan, peluang, dan tren pengembangan pertanahan dan tata ruang. 3. Memberikan rekomendasi pengembangan kebijakan pertanahan dan tata ruang yang berbasis data, praktik terbaik, dan kebutuhan pembangunan nasional. 4. Melakukan telaahan terhadap rancangan kebijakan, keputusan, atau regulasi baru terkait pertanahan dan tata ruang agar selaras dengan peraturan perundang-undangan yang berlaku. 5. Menyusun kajian strategis yang mendukung perumusan kebijakan yang efektif, aplikatif, dan implementatif di lingkungan Kementerian ATR/BPN. 6. Memberikan masukan dan saran dalam rapat teknis atau konsultasi kebijakan yang diselenggarakan oleh Kementerian ATR/BPN.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 608476);
